* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: Arial, sans-serif;
  background: #ffffff;
  color: #222;
}

#root {
  min-height: 100vh;
}

.navbar {
  width: 100%;
  min-height: 70px;
  padding: 0 60px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  position: relative;
  z-index: 1000;

  background: #ffffff;
  border-bottom: 1px solid #eeeeee;
}

.logo {
  font-size: 24px;
  font-weight: 700;
  color: #1d4ed8;
  white-space: nowrap;
}

.nav-content {
  display: flex;
  align-items: center;
  gap: 45px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 30px;
}

.nav-links a {
  text-decoration: none;
  color: #333;
  font-size: 15px;
  font-weight: 500;
}

.nav-links a:hover {
  color: #1d4ed8;
}

.nav-buttons {
  display: flex;
  align-items: center;
  gap: 12px;
}

.login-btn,
.register-btn {
  text-decoration: none;
  padding: 10px 18px;
  border-radius: 6px;

  font-size: 14px;
  font-weight: 600;
}

.login-btn {
  color: #1d4ed8;
  border: 1px solid #1d4ed8;
}

.register-btn {
  color: #ffffff;
  background: #1d4ed8;
}

/* Hamburger */

.menu-toggle {
  display: none;

  border: none;
  background: transparent;

  color: #1d4ed8;
  font-size: 28px;

  cursor: pointer;
}

@media (max-width: 768px) {
  .navbar {
    padding: 0 20px;
  }

  .menu-toggle {
    display: block;
  }

  .nav-content {
    display: none;

    position: absolute;
    top: 70px;
    left: 0;

    width: 100%;

    padding: 25px 20px;

    flex-direction: column;
    align-items: stretch;
    gap: 25px;

    background: #ffffff;
    border-top: 1px solid #eeeeee;

    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.08);
  }

  .nav-content.active {
    display: flex;
  }

  .nav-links {
    flex-direction: column;
    align-items: center;
    gap: 20px;
  }

  .nav-links a {
    font-size: 16px;
  }

  .nav-buttons {
    justify-content: center;
    width: 100%;
  }

  .login-btn,
  .register-btn {
    text-align: center;
    flex: 1;
    max-width: 130px;
  }
}

.hero {
  min-height: calc(100vh - 70px);
  padding: 70px 8%;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 60px;

  background: linear-gradient(135deg, #f8fbff, #eef5ff);
}

.hero-content {
  max-width: 650px;
}

.hero-tag {
  display: inline-block;
  padding: 8px 16px;
  margin-bottom: 20px;

  border-radius: 30px;

  background: #dbeafe;
  color: #1d4ed8;

  font-size: 14px;
  font-weight: 600;
}

.hero h1 {
  margin: 0;

  font-size: 64px;
  line-height: 1.1;
  color: #111827;
}

.hero h1 span {
  color: #1d4ed8;
}

.hero-content>p {
  max-width: 550px;
  margin: 25px 0;

  font-size: 18px;
  line-height: 1.7;
  color: #6b7280;
}

.hero-buttons {
  display: flex;
  gap: 15px;
  margin-top: 30px;
}

.primary-btn,
.secondary-btn {
  padding: 13px 24px;

  border-radius: 7px;

  font-size: 15px;
  font-weight: 600;

  cursor: pointer;
}

.primary-btn {
  border: none;
  background: #1d4ed8;
  color: white;
}

.secondary-btn {
  border: 1px solid #1d4ed8;
  background: white;
  color: #1d4ed8;
}

.hero-features {
  display: flex;
  gap: 40px;
  margin-top: 50px;
}

.hero-features div {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.hero-features strong {
  font-size: 18px;
  color: #111827;
}

.hero-features small {
  color: #6b7280;
}

.hero-card {
  width: 340px;
  padding: 35px;

  background: white;
  border-radius: 20px;

  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.08);
}

.card-icon {
  width: 55px;
  height: 55px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  background: #dbeafe;
  color: #1d4ed8;

  font-size: 25px;
  font-weight: bold;
}

.hero-card h3 {
  margin: 25px 0 8px;
  font-size: 25px;
}

.hero-card p {
  color: #6b7280;
  line-height: 1.5;
}

.loan-amount {
  display: flex;
  justify-content: space-between;
  align-items: center;

  margin: 25px 0;
  padding: 15px;

  border-radius: 10px;
  background: #f8fafc;
}

.loan-amount span {
  color: #6b7280;
  font-size: 14px;
}

.loan-amount strong {
  color: #111827;
}

.card-btn {
  width: 100%;
  padding: 13px;

  border: none;
  border-radius: 7px;

  background: #1d4ed8;
  color: white;

  font-weight: 600;
  cursor: pointer;
}

@media (max-width: 900px) {
  .hero {
    flex-direction: column;
    text-align: center;
    padding: 50px 25px;
  }

  .hero h1 {
    font-size: 45px;
  }

  .hero-buttons {
    justify-content: center;
  }

  .hero-features {
    justify-content: center;
  }

  .hero-card {
    width: 100%;
    max-width: 340px;
  }
}

.why-section {
  padding: 90px 8%;
  background: #ffffff;
}

.section-heading {
  max-width: 650px;
  margin: 0 auto 55px;
  text-align: center;
}

.section-heading span {
  color: #1d4ed8;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1.5px;
}

.section-heading h2 {
  margin: 12px 0;

  font-size: 42px;
  color: #111827;
}

.section-heading h2 strong {
  color: #1d4ed8;
}

.section-heading p {
  color: #6b7280;
  font-size: 16px;
  line-height: 1.6;
}

.why-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 22px;
}

.why-card {
  padding: 30px 25px;

  border: 1px solid #e5e7eb;
  border-radius: 14px;

  background: #ffffff;

  transition: 0.3s;
}

.why-card:hover {
  transform: translateY(-7px);

  box-shadow: 0 15px 35px rgba(0, 0, 0, 0.08);
}

.why-icon {
  width: 52px;
  height: 52px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin-bottom: 20px;

  border-radius: 12px;

  background: #dbeafe;
  color: #1d4ed8;

  font-size: 21px;
  font-weight: 700;
}

.why-card h3 {
  margin-bottom: 12px;

  font-size: 19px;
  color: #111827;
}

.why-card p {
  margin: 0;

  color: #6b7280;
  font-size: 14px;
  line-height: 1.7;
}

@media (max-width: 1000px) {
  .why-cards {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .why-section {
    padding: 70px 25px;
  }

  .section-heading h2 {
    font-size: 32px;
  }

  .why-cards {
    grid-template-columns: 1fr;
  }
}

.loans-section {
  padding: 90px 8%;
  background: #f8fafc;
}

.loan-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.loan-card {
  padding: 30px;

  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 16px;

  transition: 0.3s;
}

.loan-card:hover {
  transform: translateY(-7px);
  box-shadow: 0 15px 35px rgba(0, 0, 0, 0.08);
}

.loan-card-icon {
  width: 55px;
  height: 55px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin-bottom: 20px;

  border-radius: 12px;
  background: #dbeafe;

  font-size: 24px;
}

.loan-card h3 {
  margin: 0 0 12px;

  font-size: 20px;
  color: #111827;
}

.loan-card p {
  margin-bottom: 20px;

  color: #6b7280;
  font-size: 14px;
  line-height: 1.7;
}

.loan-card button {
  padding: 10px 0;

  border: none;
  background: transparent;

  color: #1d4ed8;
  font-size: 14px;
  font-weight: 600;

  cursor: pointer;
}

@media (max-width: 900px) {
  .loan-cards {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .loan-cards {
    grid-template-columns: 1fr;
  }
}

.process-section {
  padding: 90px 8%;
  background: #ffffff;
}

.process-container {
  display: flex;
  align-items: flex-start;
  justify-content: center;

  max-width: 1200px;
  margin: 0 auto;
}

.process-step {
  width: 220px;
  text-align: center;
}

.step-number {
  margin-bottom: 12px;

  color: #1d4ed8;
  font-size: 13px;
  font-weight: 700;
}

.step-icon {
  width: 65px;
  height: 65px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin: 0 auto 20px;

  border-radius: 50%;

  background: #dbeafe;
  color: #1d4ed8;

  font-size: 25px;
}

.process-step h3 {
  margin-bottom: 10px;

  color: #111827;
  font-size: 18px;
}

.process-step p {
  margin: 0;

  color: #6b7280;
  font-size: 14px;
  line-height: 1.6;
}

.process-line {
  width: 70px;
  height: 2px;

  margin-top: 67px;

  background: #dbeafe;
}

@media (max-width: 900px) {
  .process-container {
    flex-direction: column;
    align-items: center;
    gap: 25px;
  }

  .process-line {
    width: 2px;
    height: 40px;
    margin: 0;
  }
}

.reviews-section {
  padding: 90px 8%;
  background: #f8fafc;
}

.review-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 25px;
}

.review-card {
  padding: 30px;

  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 16px;

  transition: 0.3s;
}

.review-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 15px 35px rgba(0, 0, 0, 0.07);
}

.stars {
  margin-bottom: 18px;

  color: #f59e0b;
  font-size: 18px;
  letter-spacing: 3px;
}

.review-card>p {
  min-height: 75px;
  margin-bottom: 25px;

  color: #4b5563;
  font-size: 15px;
  line-height: 1.7;
}

.customer {
  display: flex;
  align-items: center;
  gap: 12px;

  padding-top: 20px;
  border-top: 1px solid #eeeeee;
}

.customer-avatar {
  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #dbeafe;
  color: #1d4ed8;

  font-weight: 700;
}

.customer h4 {
  margin: 0 0 4px;

  color: #111827;
  font-size: 15px;
}

.customer span {
  color: #6b7280;
  font-size: 12px;
}

@media (max-width: 900px) {
  .review-cards {
    grid-template-columns: 1fr;
  }
}

.faq-section {
  padding: 90px 8%;
  background: #ffffff;
}

.faq-container {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  margin-bottom: 15px;

  border: 1px solid #e5e7eb;
  border-radius: 10px;

  background: #ffffff;

  overflow: hidden;
}

.faq-item summary {
  padding: 20px 25px;

  color: #111827;
  font-size: 16px;
  font-weight: 600;

  cursor: pointer;
  list-style: none;
}

.faq-item summary::-webkit-details-marker {
  display: none;
}

.faq-item summary::after {
  content: "+";

  float: right;

  color: #1d4ed8;
  font-size: 22px;
  font-weight: 400;
}

.faq-item[open] summary::after {
  content: "−";
}

.faq-item p {
  margin: 0;
  padding: 0 25px 20px;

  color: #6b7280;
  font-size: 14px;
  line-height: 1.7;
}

.footer {
  padding-top: 70px;
  background: #111827;
  color: #ffffff;
}

.footer-container {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 50px;

  padding: 0 8% 60px;
}

.footer-about {
  max-width: 350px;
}

.footer-about h2 {
  margin-bottom: 18px;

  color: #ffffff;
  font-size: 25px;
}

.footer-about p {
  color: #9ca3af;
  font-size: 14px;
  line-height: 1.7;
}

.footer-social {
  display: flex;
  gap: 10px;
  margin-top: 25px;
}

.footer-social span {
  width: 35px;
  height: 35px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #1f2937;
  color: #ffffff;

  font-size: 12px;
  font-weight: 600;
}

.footer-column {
  display: flex;
  flex-direction: column;
  gap: 13px;
}

.footer-column h3 {
  margin-bottom: 10px;

  font-size: 16px;
  color: #ffffff;
}

.footer-column a {
  color: #9ca3af;
  text-decoration: none;
  font-size: 14px;
}

.footer-column a:hover {
  color: #ffffff;
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 20px 8%;

  border-top: 1px solid #1f2937;
}

.footer-bottom p {
  margin: 0;
  color: #6b7280;
  font-size: 13px;
}

.footer-bottom div {
  display: flex;
  gap: 25px;
}

.footer-bottom a {
  color: #6b7280;
  text-decoration: none;
  font-size: 13px;
}

.footer-bottom a:hover {
  color: #ffffff;
}

@media (max-width: 800px) {
  .footer-container {
    grid-template-columns: 1fr 1fr;
  }

  .footer-about {
    max-width: none;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 15px;
    text-align: center;
  }
}

@media (max-width: 500px) {
  .footer-container {
    grid-template-columns: 1fr;
  }
}

/* ================================
   LOANS PAGE
================================ */

.loans-page {
  width: 100%;
}

/* Loans Hero */

.loans-hero {
  min-height: 360px;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 70px 8%;

  text-align: center;

  background: linear-gradient(135deg, #f8fbff, #eef5ff);
}

.loans-hero-content {
  max-width: 700px;
}

.loans-hero-content>span {
  color: #1d4ed8;

  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1.5px;
}

.loans-hero-content h1 {
  margin: 15px 0;

  color: #111827;

  font-size: 48px;
  line-height: 1.2;
}

.loans-hero-content h1 strong {
  color: #1d4ed8;
}

.loans-hero-content p {
  margin: 0 auto;

  max-width: 600px;

  color: #6b7280;

  font-size: 16px;
  line-height: 1.7;
}

/* All Loans */

.all-loans-section {
  padding: 90px 8%;

  background: #ffffff;
}

.all-loan-cards {
  max-width: 1100px;

  display: grid;
  grid-template-columns: repeat(3, 1fr);

  gap: 25px;

  margin: 0 auto;
}

.all-loan-card {
  padding: 30px;

  background: #ffffff;

  border: 1px solid #e5e7eb;
  border-radius: 16px;

  transition: 0.3s;
}

.all-loan-card:hover {
  transform: translateY(-7px);

  box-shadow: 0 15px 35px rgba(0, 0, 0, 0.08);
}

.all-loan-icon {
  width: 60px;
  height: 60px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin-bottom: 22px;

  border-radius: 14px;

  background: #dbeafe;

  font-size: 26px;
}

.all-loan-card h3 {
  margin: 0 0 12px;

  color: #111827;

  font-size: 21px;
}

.all-loan-card>p {
  min-height: 75px;

  margin: 0 0 20px;

  color: #6b7280;

  font-size: 14px;
  line-height: 1.7;
}

.loan-info {
  display: flex;
  flex-direction: column;

  gap: 8px;

  margin-bottom: 20px;
}

.loan-info span {
  color: #4b5563;

  font-size: 13px;
}

.loan-info span::before {
  content: "✓";

  margin-right: 8px;

  color: #1d4ed8;

  font-weight: bold;
}

.all-loan-card button {
  width: 100%;

  padding: 12px;

  border: none;
  border-radius: 7px;

  background: #1d4ed8;

  color: #ffffff;

  font-size: 14px;
  font-weight: 600;

  cursor: pointer;
}

.all-loan-card button:hover {
  background: #1741b5;
}

@media (max-width: 900px) {

  .all-loan-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .loans-hero-content h1 {
    font-size: 40px;
  }
}

@media (max-width: 600px) {

  .loans-hero {
    min-height: 300px;

    padding: 50px 25px;
  }

  .loans-hero-content h1 {
    font-size: 34px;
  }

  .all-loans-section {
    padding: 70px 25px;
  }

  .all-loan-cards {
    grid-template-columns: 1fr;
  }
}

/* ================================
   ABOUT PAGE
================================ */

.about-page {
  width: 100%;
}

/* About Hero */

.about-hero {
  min-height: 360px;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 70px 8%;

  text-align: center;

  background: linear-gradient(135deg, #f8fbff, #eef5ff);
}

.about-hero-content {
  max-width: 700px;
}

.about-hero-content>span,
.about-story-text>span {
  color: #1d4ed8;

  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1.5px;
}

.about-hero-content h1 {
  margin: 15px 0;

  color: #111827;

  font-size: 48px;
  line-height: 1.2;
}

.about-hero-content h1 strong {
  color: #1d4ed8;
}

.about-hero-content p {
  max-width: 600px;

  margin: 0 auto;

  color: #6b7280;

  font-size: 16px;
  line-height: 1.7;
}

/* Story */

.about-story {
  padding: 90px 8%;

  background: #ffffff;
}

.about-story-content {
  max-width: 1100px;

  display: grid;
  grid-template-columns: 1.3fr 0.7fr;

  align-items: center;

  gap: 80px;

  margin: 0 auto;
}

.about-story-text h2 {
  margin: 15px 0 20px;

  color: #111827;

  font-size: 40px;
  line-height: 1.2;
}

.about-story-text h2 strong {
  color: #1d4ed8;
}

.about-story-text p {
  margin-bottom: 18px;

  color: #6b7280;

  font-size: 15px;
  line-height: 1.8;
}

.about-highlight {
  padding: 45px 35px;

  border-radius: 20px;

  background: #f8fafc;

  border: 1px solid #e5e7eb;

  text-align: center;
}

.about-highlight-icon {
  width: 70px;
  height: 70px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin: 0 auto 25px;

  border-radius: 18px;

  background: #dbeafe;

  color: #1d4ed8;

  font-size: 30px;
  font-weight: 700;
}

.about-highlight h3 {
  margin-bottom: 12px;

  color: #111827;

  font-size: 23px;
}

.about-highlight p {
  margin: 0;

  color: #6b7280;

  font-size: 14px;
  line-height: 1.7;
}

/* Values */

.about-values {
  padding: 90px 8%;

  background: #f8fafc;
}

.about-value-cards {
  max-width: 1000px;

  display: grid;
  grid-template-columns: repeat(3, 1fr);

  gap: 25px;

  margin: 0 auto;
}

.about-value-card {
  padding: 30px;

  background: #ffffff;

  border: 1px solid #e5e7eb;
  border-radius: 16px;

  text-align: center;

  transition: 0.3s;
}

.about-value-card:hover {
  transform: translateY(-6px);

  box-shadow: 0 15px 35px rgba(0, 0, 0, 0.08);
}

.about-value-icon {
  width: 55px;
  height: 55px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin: 0 auto 20px;

  border-radius: 14px;

  background: #dbeafe;

  font-size: 23px;
}

.about-value-card h3 {
  margin-bottom: 12px;

  color: #111827;

  font-size: 19px;
}

.about-value-card p {
  margin: 0;

  color: #6b7280;

  font-size: 14px;
  line-height: 1.7;
}

@media (max-width: 800px) {

  .about-hero {
    min-height: 300px;
    padding: 50px 25px;
  }

  .about-hero-content h1 {
    font-size: 36px;
  }

