================================ */

.help-page {
  width: 100%;
}

.help-hero {
  min-height: 360px;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 70px 8%;

  text-align: center;

  background: linear-gradient(135deg, #f8fbff, #eef5ff);
}

.help-hero-content {
  max-width: 700px;
}

.help-hero-content>span,
.help-info-box>div>span {
  color: #1d4ed8;

  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1.5px;
}

.help-hero-content h1 {
  margin: 15px 0;

  color: #111827;

  font-size: 48px;
  line-height: 1.2;
}

.help-hero-content h1 strong {
  color: #1d4ed8;
}

.help-hero-content p {
  max-width: 600px;

  margin: 0 auto;

  color: #6b7280;

  font-size: 16px;
  line-height: 1.7;
}

.help-section {
  padding: 90px 8%;

  background: #ffffff;
}

.help-cards {
  max-width: 1000px;

  display: grid;
  grid-template-columns: repeat(3, 1fr);

  gap: 25px;

  margin: 0 auto;
}

.help-card {
  padding: 30px;

  border: 1px solid #e5e7eb;
  border-radius: 16px;

  background: #ffffff;

  transition: 0.3s;
}

.help-card:hover {
  transform: translateY(-7px);

  box-shadow: 0 15px 35px rgba(0, 0, 0, 0.08);
}

.help-icon {
  width: 55px;
  height: 55px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin-bottom: 20px;

  border-radius: 14px;

  background: #dbeafe;

  font-size: 23px;
}

.help-card h3 {
  margin-bottom: 12px;

  color: #111827;

  font-size: 19px;
}

.help-card p {
  min-height: 70px;

  margin-bottom: 20px;

  color: #6b7280;

  font-size: 14px;
  line-height: 1.7;
}

.help-card a {
  color: #1d4ed8;

  text-decoration: none;

  font-size: 14px;
  font-weight: 600;
}

.help-info-section {
  padding: 0 8% 90px;

  background: #ffffff;
}

.help-info-box {
  max-width: 1000px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 30px;

  margin: 0 auto;
  padding: 40px;

  border-radius: 18px;

  background: #f8fafc;
  border: 1px solid #e5e7eb;
