.help-info-box h2 {
  margin: 10px 0;

  color: #111827;

  font-size: 28px;
}

.help-info-box p {
  max-width: 550px;

  margin: 0;

  color: #6b7280;

  font-size: 14px;
  line-height: 1.7;
}

.help-contact-btn {
  padding: 13px 22px;

  border-radius: 7px;

  background: #1d4ed8;
  color: #ffffff;

  text-decoration: none;

  font-size: 14px;
  font-weight: 600;

  white-space: nowrap;
}

@media (max-width: 800px) {

  .help-hero {
    min-height: 300px;
    padding: 50px 25px;
  }

  .help-hero-content h1 {
    font-size: 36px;
  }

  .help-section {
    padding: 70px 25px;
