================================ */

.auth-page {
  min-height: calc(100vh - 70px);

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 60px 25px;

  background: linear-gradient(135deg, #f8fbff, #eef5ff);
}

.auth-container {
  width: 100%;
  max-width: 1000px;

  display: grid;
  grid-template-columns: 0.9fr 1.1fr;

  align-items: center;

  gap: 70px;
}

.auth-brand h1 {
  margin-bottom: 15px;

  color: #1d4ed8;

  font-size: 42px;
}

.auth-brand p {
  max-width: 400px;

  color: #6b7280;

  font-size: 16px;
  line-height: 1.7;
}

.auth-card {
  padding: 40px;

  background: #ffffff;

  border: 1px solid #e5e7eb;
  border-radius: 18px;

  box-shadow: 0 20px 45px rgba(0, 0, 0, 0.07);
}

.auth-heading {
  margin-bottom: 30px;
}

.auth-heading span {
  color: #1d4ed8;

  font-size: 12px;
  font-weight: 700;
  letter-spacing: 1.5px;
}

.auth-heading h2 {
  margin: 10px 0 8px;

  color: #111827;

  font-size: 27px;
}

.auth-heading p {
  margin: 0;

  color: #6b7280;

  font-size: 14px;
}

.auth-options {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin: 5px 0 22px;
}

