  align-items: center;

  gap: 15px;

  margin: 25px 0;
}

.auth-divider::before,
.auth-divider::after {
  content: "";

  flex: 1;

  height: 1px;

  background: #e5e7eb;
}

.auth-divider span {
  color: #9ca3af;

  font-size: 12px;
}

.auth-register {
  margin: 0;

  text-align: center;

  color: #6b7280;

  font-size: 14px;
}

.auth-register a {
  margin-left: 5px;

  color: #1d4ed8;

  text-decoration: none;

  font-weight: 600;
}

@media (max-width: 800px) {

