  line-height: 1.5;

  cursor: pointer;
}

.terms-check input {
  margin-top: 3px;

  accent-color: #1d4ed8;
}

.loan-input {
  margin: 25px 0 15px;
}

.loan-input label {
  display: block;

  margin-bottom: 8px;

  color: #374151;

  font-size: 13px;
  font-weight: 600;
}

.amount-input {
  display: flex;
  align-items: center;

  border: 1px solid #d1d5db;
  border-radius: 8px;

  background: #ffffff;

  overflow: hidden;
}

.amount-input span {
  padding-left: 14px;

  color: #6b7280;
  font-weight: 600;
}

.amount-input input {
  width: 100%;

  padding: 12px;

  border: none;
  outline: none;

  font-size: 15px;
}

.amount-input input::-webkit-outer-spin-button,
.amount-input input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.eligibility-result {
  margin: 15px 0 0;

  padding: 12px;

  border-radius: 8px;

  background: #eff6ff;
  color: #1d4ed8;

  font-size: 13px;
  line-height: 1.5;
}

/* ================================
   LOAN APPLICATION
================================ */

/* ================= APPLICATION FORM ================= */

.application-page {
  min-height: 100vh;
  background: #f6f8fc;
}

.application-section {
  padding: 60px 20px 80px;
}

.application-card {
  width: min(100%, 1000px);
  margin: 0 auto;
  padding: 45px;
  background: #fff;
  border-radius: 20px;
  box-sizing: border-box;
}

.application-heading {
  margin-bottom: 40px;
}

.application-heading h2 {
  margin: 8px 0;
  font-size: 32px;
}

.application-heading p {
  margin: 0;
  color: #64748b;
}

.form-section {
  margin-bottom: 45px;
  padding-bottom: 35px;
  border-bottom: 1px solid #e5e7eb;
}

.form-section-title {
  display: flex;
  align-items: flex-start;
  gap: 15px;
  margin-bottom: 25px;
}

.form-section-title>span {
  min-width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: #eaf1ff;
  color: #2563eb;
  font-weight: 700;
}

.form-section-title h3 {
  margin: 0 0 5px;
  font-size: 20px;
}

.form-section-title p {
  margin: 0;
  color: #64748b;
  font-size: 14px;
}

.application-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
}

.form-group {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.full-width {
  grid-column: 1 / -1;
}

.form-group label,
.document-upload>label {
  font-size: 14px;
  font-weight: 600;
  color: #1e293b;
}

.form-group input,
.form-group select {
  width: 100%;
  min-height: 48px;
  padding: 12px 14px;
  box-sizing: border-box;
  border: 1px solid #dbe2ea;
  border-radius: 10px;
  background: #fff;
  font-size: 15px;
  outline: none;
}

.form-group input:focus,
.form-group select:focus {
  border-color: #2563eb;
}

.form-group small {
  color: #64748b;
  font-size: 12px;
}

.input-with-symbol {
  display: flex;
  align-items: center;
  min-height: 48px;
  border: 1px solid #dbe2ea;
  border-radius: 10px;
  overflow: hidden;
}

.input-with-symbol span {
  padding-left: 15px;
  font-weight: 600;
}

.input-with-symbol input {
  border: none;
  outline: none;
}

/* OTP */

.phone-otp-row {
  display: flex;
  gap: 10px;
}

.phone-otp-row input {
  flex: 1;
}

.otp-btn {
  flex-shrink: 0;
  padding: 0 20px;
  border: none;
  border-radius: 10px;
  background: #2563eb;
  color: white;
  font-weight: 600;
  cursor: pointer;
}

.verified-text {
  color: #16a34a !important;
  font-weight: 600;
}

/* DOCUMENT UPLOAD */

.document-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
}

.document-upload {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.upload-box {
  position: relative;
  min-height: 150px;
  padding: 25px;
  box-sizing: border-box;
  border: 2px dashed #d5dce6;
  border-radius: 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 7px;
  cursor: pointer;
  background: #fafbfc;
}

.upload-icon {
  font-size: 28px;
}

.upload-box strong {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
}

.upload-box small {
  color: #64748b;
}

.upload-box input[type="file"] {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
}

/* ELIGIBILITY */

.eligibility-box {
  margin-top: 20px;
  padding: 25px;
  border-radius: 15px;
  background: #f1f5ff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}

.eligibility-box h3 {
  margin: 0 0 6px;
}

.eligibility-box p {
  margin: 0;
  color: #64748b;
}

.eligibility-btn {
  flex-shrink: 0;
  padding: 13px 22px;
  border: none;
  border-radius: 10px;
  background: #2563eb;
  color: white;
  font-weight: 600;
  cursor: pointer;
}

.eligibility-message {
  margin-top: 20px;
  padding: 18px 20px;
  border-radius: 12px;
}

.eligibility-message p {
  margin: 6px 0 0;
}

.eligibility-message.success {
  background: #dcfce7;
  color: #166534;
}

.eligibility-message.warning {
  background: #fef3c7;
  color: #92400e;
}

.eligibility-message.error {
  background: #fee2e2;
  color: #991b1b;
}

.application-submit {
  width: 100%;
  margin-top: 25px;
  padding: 16px;
  border: none;
  border-radius: 10px;
  background: #2563eb;
  color: white;
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
}

/* MOBILE */

@media (max-width: 768px) {
  .application-section {
    padding: 35px 12px 50px;
  }

  .application-card {
    padding: 25px 18px;
    border-radius: 15px;
  }

  .application-heading h2 {
    font-size: 26px;
  }

  .application-grid,
  .document-grid {
    grid-template-columns: 1fr;
  }

  .full-width {
    grid-column: auto;
  }

  .phone-otp-row {
    flex-direction: column;
  }

  .otp-btn {
    min-height: 46px;
  }

  .eligibility-box {
    flex-direction: column;
    align-items: stretch;
  }

  .eligibility-btn {
    width: 100%;
  }
}

/* OTP INPUT */

.otp-input-wrapper {
  position: relative;
  width: 100%;
}

.otp-input-wrapper input {
  width: 100%;
  min-height: 50px;
  padding: 12px 55px 12px 15px;
  box-sizing: border-box;
  border: 1px solid #dbe2ea;
  border-radius: 10px;
  font-size: 18px;
  letter-spacing: 4px;
  outline: none;
}

.otp-input-wrapper input:focus {
  border-color: #2563eb;
}

.otp-status {
  position: absolute;
  right: 15px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 25px;
  font-weight: 700;
}

.otp-status.success {
  color: #16a34a;
}

.otp-status.error {
  color: #dc2626;
}

.otp-action-row {
  display: flex;
  align-items: center;
  gap: 15px;
  margin-top: 10px;
}

.verified-text {
  color: #16a34a;
  font-size: 14px;
  font-weight: 600;
}

.otp-error-text {
  color: #dc2626;
  font-size: 14px;
  font-weight: 600;
}

