.application-heading>span {
  display: inline-block;
  margin-bottom: 10px;
  color: #f0a500;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 2px;
}

.application-heading h2 {
  margin: 0;
  font-size: 32px;
  color: #101828;
}

.application-heading p {
  margin: 10px 0 0;
  color: #667085;
  font-size: 15px;
}


/* =====================================================
   FORM SECTION
===================================================== */

.form-section {
  margin-bottom: 42px;
  padding-bottom: 38px;
  border-bottom: 1px solid #eaecf0;
}

.form-section:last-of-type {
  border-bottom: none;
}

.form-section-title {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 25px;
}

.form-section-title>span {
  flex-shrink: 0;
  width: 42px;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  background: #101828;
  color: #ffffff;
  font-size: 14px;
  font-weight: 700;
}

.form-section-title h3 {
  margin: 0 0 5px;
  font-size: 20px;
  color: #101828;
}

.form-section-title p {
  margin: 0;
  color: #667085;
  font-size: 14px;
}


/* =====================================================
   FORM GRID
===================================================== */

.application-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
}

.full-width {
  grid-column: 1 / -1;
}


/* =====================================================
   FORM GROUP
===================================================== */

.form-group {
  min-width: 0;
}

.form-group label {
  display: block;
  margin-bottom: 9px;
  color: #344054;
  font-size: 14px;
  font-weight: 600;
}

.form-group input,
.form-group select {
  width: 100%;
  height: 52px;
  box-sizing: border-box;
  padding: 0 15px;
  border: 1px solid #d0d5dd;
  border-radius: 10px;
  outline: none;
  background: #ffffff;
  color: #101828;
  font-size: 15px;
  transition: 0.2s ease;
}

.form-group input::placeholder {
  color: #98a2b3;
}

.form-group input:focus,
.form-group select:focus {
  border-color: #f0a500;
  box-shadow: 0 0 0 3px rgba(240, 165, 0, 0.12);
}

.form-group small {
  display: block;
  margin-top: 8px;
  color: #667085;
  font-size: 12px;
  line-height: 1.5;
}


/* =====================================================
   RUPEE INPUT
===================================================== */

.input-with-symbol {
  position: relative;
}

.input-with-symbol>span {
  position: absolute;
  left: 15px;
  top: 50%;
  transform: translateY(-50%);
  z-index: 1;
  color: #667085;
  font-weight: 700;
}

.input-with-symbol input {
  padding-left: 35px;
}


/* =====================================================
   PHONE + OTP
===================================================== */

.phone-otp-row {
  display: flex;
  gap: 12px;
  align-items: center;
}

.phone-otp-row input {
  flex: 1;
  min-width: 0;
}

.otp-btn {
  flex-shrink: 0;
  height: 52px;
  padding: 0 20px;
  border: none;
  border-radius: 10px;
  background: #101828;
  color: #ffffff;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: 0.2s ease;
}

.otp-btn:hover {
  background: #344054;
  transform: translateY(-1px);
}


/* =====================================================
   OTP INPUT + STATUS
===================================================== */

.otp-input-wrapper {
  position: relative;
  width: 100%;
}

.otp-input-wrapper input {
  padding-right: 55px;
  letter-spacing: 5px;
  font-weight: 600;
}

.otp-status {
  position: absolute;
  right: 15px;
  top: 50%;
  width: 28px;
  height: 28px;
  transform: translateY(-50%);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  font-size: 16px;
  font-weight: 800;
}

.otp-status.success {
  background: #dcfae6;
  color: #067647;
}

.otp-status.error {
  background: #fee4e2;
  color: #b42318;
}

.verify-btn {
  margin-top: 12px;
}

.verified-text {
  color: #067647 !important;
  font-weight: 600;
}

.otp-error-text {
  color: #b42318 !important;
  font-weight: 600;
}


/* =====================================================
   DOCUMENT UPLOAD
===================================================== */

.document-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
}

.document-upload {
  min-width: 0;
}

.document-upload>label {
  display: block;
  margin-bottom: 9px;
  color: #344054;
  font-size: 14px;
  font-weight: 600;
}

.upload-box {
  position: relative;
  min-height: 155px;
  padding: 25px 20px;
  box-sizing: border-box;
  border: 2px dashed #d0d5dd;
  border-radius: 14px;
  background: #f9fafb;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  cursor: pointer;
  overflow: hidden;
  transition: 0.2s ease;
}

.upload-box:hover {
  border-color: #f0a500;
  background: #fffcf5;
}

.upload-icon {
  margin-bottom: 10px;
  font-size: 30px;
}

.upload-box strong {
  max-width: 90%;
  color: #344054;
  font-size: 14px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.upload-box small {
  margin-top: 7px;
  color: #98a2b3;
  font-size: 12px;
}

.upload-box input[type="file"] {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
}


/* =====================================================
   SELFIE START
===================================================== */

.selfie-start {
  padding: 35px 25px;
  border: 1px solid #eaecf0;
  border-radius: 18px;
  background: #f9fafb;
  text-align: center;
}

.selfie-icon {
  width: 65px;
  height: 65px;
  margin: 0 auto 15px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #101828;
  font-size: 28px;
}

.selfie-start h3 {
  margin: 0 0 8px;
  color: #101828;
  font-size: 20px;
}

.selfie-start p {
  max-width: 560px;
  margin: 0 auto 22px;
  color: #667085;
  font-size: 14px;
  line-height: 1.7;
}


/* =====================================================
   CAMERA BUTTON
===================================================== */

.camera-btn,
.capture-btn {
  border: none;
  border-radius: 10px;
  background: #101828;
  color: #ffffff;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition: 0.2s ease;
}

.camera-btn {
  padding: 14px 28px;
}

.camera-btn:hover,
.capture-btn:hover {
  background: #344054;
  transform: translateY(-1px);
}


/* =====================================================
   CAMERA CONTAINER
===================================================== */

.camera-container {
  padding: 20px;
  border: 1px solid #eaecf0;
  border-radius: 18px;
  background: #f9fafb;
  text-align: center;
}

.camera-preview {
  position: relative;
  width: min(650px, 100%);
  margin: 0 auto;
  overflow: hidden;
  border-radius: 16px;
  background: #101010;
  aspect-ratio: 16 / 10;
}

.camera-preview video {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transform: scaleX(-1);
}


/* =====================================================
   FACE GUIDE
===================================================== */

.face-guide {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.face-oval {
  width: 42%;
  height: 70%;
  border: 3px solid rgba(255, 255, 255, 0.9);
  border-radius: 50%;
  box-shadow:
    0 0 0 9999px rgba(0, 0, 0, 0.25);
}


/* =====================================================
   CAMERA INSTRUCTIONS
===================================================== */

.camera-instructions {
  margin: 18px auto;
}

.camera-instructions p {
  margin: 4px 0;
  color: #667085;
  font-size: 13px;
}


/* =====================================================
   CAPTURE / CANCEL
===================================================== */

.capture-btn {
  padding: 14px 28px;
  margin-right: 10px;
}

.cancel-camera-btn {
  padding: 13px 22px;
  border: 1px solid #d0d5dd;
  border-radius: 10px;
  background: #ffffff;
  color: #344054;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}

.cancel-camera-btn:hover {
  background: #f2f4f7;
}


/* =====================================================
   SELFIE RESULT
===================================================== */

.selfie-result {
  padding: 22px;
  border: 1px solid #eaecf0;
  border-radius: 18px;
  background: #f9fafb;
  text-align: center;
}

.selfie-preview {
  width: min(380px, 100%);
  margin: 0 auto 20px;
  overflow: hidden;
  border-radius: 16px;
  background: #101010;
}

.selfie-preview img {
  display: block;
  width: 100%;
  height: auto;
}


/* =====================================================
   SELFIE SUCCESS
===================================================== */

.selfie-success,
.selfie-error {
  width: min(500px, 100%);
  margin: 0 auto 18px;
  padding: 15px;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 13px;
  border-radius: 12px;
  text-align: left;
}

.selfie-success {
  background: #ecfdf3;
  border: 1px solid #abefc6;
}

.selfie-error {
  background: #fef3f2;
  border: 1px solid #fecdca;
}

.selfie-success>span,
.selfie-error>span {
  width: 35px;
  height: 35px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  font-size: 18px;
  font-weight: 800;
}

.selfie-success>span {
  background: #12b76a;
  color: #ffffff;
}

.selfie-error>span {
  background: #f04438;
  color: #ffffff;
}

.selfie-success strong {
  color: #067647;
}

.selfie-error strong {
  color: #b42318;
}

.selfie-success p,
.selfie-error p {
  margin: 3px 0 0;
  font-size: 13px;
}

.selfie-success p {
  color: #475467;
}

.selfie-error p {
  color: #667085;
}


/* =====================================================
   RETAKE BUTTON
===================================================== */

.retake-btn {
  padding: 12px 22px;
  border: 1px solid #d0d5dd;
  border-radius: 10px;
  background: #ffffff;
  color: #344054;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}

.retake-btn:hover {
  background: #f2f4f7;
}


/* =====================================================
   ELIGIBILITY
===================================================== */

.eligibility-box {
  margin-top: 15px;
  padding: 25px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
  border: 1px solid #eaecf0;
  border-radius: 16px;
  background: #f9fafb;
}

.eligibility-box h3 {
  margin: 0 0 7px;
  color: #101828;
  font-size: 18px;
}

.eligibility-box p {
  margin: 0;
  color: #667085;
  font-size: 13px;
  line-height: 1.5;
}

.eligibility-btn {
  flex-shrink: 0;
  padding: 14px 22px;
  border: none;
  border-radius: 10px;
  background: #f0a500;
  color: #101828;
  font-size: 14px;
  font-weight: 800;
  cursor: pointer;
  transition: 0.2s ease;
}

.eligibility-btn:hover {
  background: #d99100;
  transform: translateY(-1px);
}


/* =====================================================
   ELIGIBILITY MESSAGE
===================================================== */

.eligibility-message {
  margin-top: 15px;
  padding: 17px 20px;
  border-radius: 12px;
}

.eligibility-message strong {
  display: block;
  margin-bottom: 5px;
  font-size: 15px;
}

.eligibility-message p {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
}

.eligibility-message.success {
  background: #ecfdf3;
  border: 1px solid #abefc6;
  color: #067647;
}

.eligibility-message.warning {
  background: #fffaeb;
  border: 1px solid #fedf89;
  color: #b54708;
}

.eligibility-message.error {
  background: #fef3f2;
  border: 1px solid #fecdca;
  color: #b42318;
}


/* =====================================================
   SUBMIT
===================================================== */

.application-submit {
  width: 100%;
  height: 56px;
  margin-top: 25px;
  border: none;
  border-radius: 12px;
  background: #101828;
  color: #ffffff;
  font-size: 15px;
  font-weight: 700;
  cursor: pointer;
  transition: 0.2s ease;
}

.application-submit:hover {
  background: #344054;
  transform: translateY(-1px);
}


/* =====================================================
   TABLET
===================================================== */

@media (max-width: 768px) {

  .application-hero {
    padding: 65px 20px 55px;
  }

  .application-section {
    padding: 40px 15px 70px;
  }

  .application-card {
    padding: 30px 22px;
    border-radius: 18px;
  }

  .application-heading {
    margin-bottom: 35px;
  }

  .application-heading h2 {
    font-size: 27px;
  }

  .application-grid,
  .document-grid {
    grid-template-columns: 1fr;
  }

  .full-width {
    grid-column: auto;
  }

  .eligibility-box {
    align-items: stretch;
    flex-direction: column;
  }

  .eligibility-btn {
    width: 100%;
  }

}


/* =====================================================
   MOBILE
===================================================== */

@media (max-width: 600px) {

  .application-hero {
    padding: 50px 16px 45px;
  }

  .application-hero>span {
    font-size: 11px;
  }

  .application-hero h1 {
    font-size: 38px;
  }

  .application-hero p {
    font-size: 14px;
  }

  .application-section {
    padding: 25px 12px 55px;
  }

  .application-card {
    padding: 25px 16px;
    border-radius: 16px;
  }

  .application-heading h2 {
    font-size: 24px;
  }

  .application-heading p {
    font-size: 13px;
  }

  .form-section {
    margin-bottom: 32px;
    padding-bottom: 30px;
  }

  .form-section-title {
    gap: 12px;
  }

  .form-section-title>span {
    width: 36px;
    height: 36px;
    border-radius: 9px;
    font-size: 12px;
  }

  .form-section-title h3 {
    font-size: 17px;
  }

  .form-section-title p {
    font-size: 12px;
  }

  .application-grid {
    gap: 18px;
  }

  .phone-otp-row {
    flex-direction: column;
    align-items: stretch;
  }

  .phone-otp-row .otp-btn {
    width: 100%;
  }

  .otp-btn {
    height: 48px;
  }

  .camera-container {
    padding: 12px;
  }

  .camera-preview {
    aspect-ratio: 3 / 4;
  }

  .face-oval {
    width: 58%;
    height: 58%;
  }

  .capture-btn,
  .cancel-camera-btn {
    width: 100%;
    margin: 5px 0;
  }

  .selfie-start {
    padding: 28px 18px;
  }

  .eligibility-box {
    padding: 20px;
  }

  .application-submit {
    height: 54px;
  }
}


/* =====================================================
   SMALL MOBILE
===================================================== */

@media (max-width: 380px) {

  .application-card {
    padding: 20px 13px;
  }

  .application-hero h1 {
    font-size: 33px;
  }

  .form-section-title h3 {
    font-size: 16px;
  }

  .form-section-title p {
    font-size: 11px;
  }

  .form-group input,
  .form-group select {
    height: 48px;
    font-size: 14px;
  }

}

/* ================= SELFIE CAMERA ================= */

.selfie-section {
  margin-top: 40px;
  padding-top: 35px;
  border-top: 1px solid #e5e7eb;
}

.selfie-section-title {
  display: flex;
  align-items: center;
  gap: 15px;
  margin-bottom: 25px;
}

.selfie-section-title>span {
  width: 42px;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #111827;
  color: white;
  font-size: 14px;
  font-weight: 700;
}

.selfie-section-title h3 {
  margin: 0 0 5px;
  font-size: 20px;
  color: #111827;
}

.selfie-section-title p {
  margin: 0;
  color: #6b7280;
  font-size: 14px;
}

/* Camera box */

.selfie-camera-wrapper {
  max-width: 600px;
  margin: 0 auto;
}

.camera-box {
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  border-radius: 20px;
  background: #111827;
  border: 2px solid #e5e7eb;
}

/* Video */

.camera-box video {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  transform: scaleX(-1);
}

/* Face frame */

.face-frame {
  position: absolute;
  width: 48%;
  height: 72%;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  border: 3px solid rgba(255, 255, 255, 0.9);
  border-radius: 50%;
  pointer-events: none;
  box-shadow:
    0 0 0 9999px rgba(0, 0, 0, 0.28);
}

/* Camera instruction */

.camera-instruction {
  position: absolute;
  left: 50%;
  top: 20px;
  transform: translateX(-50%);
  width: max-content;
  max-width: 90%;
  padding: 9px 16px;
  border-radius: 30px;
  background: rgba(0, 0, 0, 0.65);
  color: white;
  font-size: 13px;
  text-align: center;
  backdrop-filter: blur(5px);
}

/* Camera buttons */

.camera-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 18px;
}

.open-camera-btn,
.capture-selfie-btn,
.retake-selfie-btn {
  border: none;
  border-radius: 10px;
  padding: 13px 22px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: 0.2s ease;
}

.open-camera-btn,
.capture-selfie-btn {
  background: #111827;
  color: white;
}

.open-camera-btn:hover,
.capture-selfie-btn:hover {
  transform: translateY(-1px);
  opacity: 0.9;
}

.retake-selfie-btn {
  background: #f3f4f6;
  color: #111827;
}

.retake-selfie-btn:hover {
  background: #e5e7eb;
}

/* Captured selfie */

.selfie-preview {
  position: relative;
  max-width: 420px;
  margin: 0 auto;
}

.selfie-preview img {
  display: block;
  width: 100%;
  border-radius: 18px;
  border: 2px solid #d1d5db;
}

/* Success badge */

.selfie-success-badge {
  position: absolute;
  right: 12px;
  top: 12px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  border-radius: 20px;
  background: #16a34a;
  color: white;
  font-size: 13px;
  font-weight: 600;
}

/* Status */

.selfie-status {
  margin-top: 15px;
  padding: 13px 16px;
  border-radius: 10px;
  font-size: 14px;
  line-height: 1.5;
}

.selfie-status.success {
  background: #ecfdf5;
  color: #15803d;
  border: 1px solid #bbf7d0;
}

.selfie-status.error {
  background: #fef2f2;
  color: #dc2626;
  border: 1px solid #fecaca;
}

.selfie-status.warning {
  background: #fffbeb;
  color: #b45309;
  border: 1px solid #fde68a;
}

/* Hidden canvas */

.selfie-canvas {
  display: none;
}

/* Mobile */

@media (max-width: 768px) {

  .selfie-section {
    margin-top: 30px;
    padding-top: 25px;
  }

  .selfie-section-title {
    align-items: flex-start;
  }

  .selfie-section-title h3 {
    font-size: 18px;
  }

  .selfie-section-title p {
    font-size: 13px;
  }

  .camera-box {
    aspect-ratio: 3 / 4;
    border-radius: 16px;
  }

  .face-frame {
    width: 62%;
    height: 55%;
  }

  .camera-instruction {
    top: 15px;
    font-size: 12px;
    padding: 8px 12px;
  }

  .camera-controls {
    flex-direction: column;
  }

  .open-camera-btn,
  .capture-selfie-btn,
  .retake-selfie-btn {
    width: 100%;
  }

  .selfie-preview {
    max-width: 100%;
  }
}

