  width: 100%;
  height: 390px;
  overflow: hidden;
  border-radius: 20px;
  background: #000;
}

.selfie-video {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  transform: scaleX(-1);
}

/* Overlay */

.camera-overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

/* FACE FRAME */

.face-frame {
  position: absolute;

  width: 48%;
  height: 70%;

  left: 50%;
  top: 50%;

  transform: translate(-50%, -50%);

  border: 3px solid rgba(255, 255, 255, 0.85);

  border-radius: 48% 48% 45% 45%;

  box-shadow:
    0 0 0 9999px rgba(0, 0, 0, 0.30);

  transition: 0.2s ease;
}

.face-frame.face-good {
  border-color: #22c55e;

  box-shadow:
    0 0 0 9999px rgba(0, 0, 0, 0.25),
    0 0 20px rgba(34, 197, 94, 0.6);
}

.face-frame.face-warning {
  border-color: #f59e0b;
}

/* STATUS */

.camera-status {
  position: absolute;
  left: 50%;
  bottom: 18px;
  transform: translateX(-50%);

  background: rgba(0, 0, 0, 0.7);

  padding: 9px 16px;

  border-radius: 30px;

  white-space: nowrap;

  font-size: 14px;
  font-weight: 600;
}

.status-red {
  color: #f87171;
}

.status-green {
  color: #4ade80;
}

/* BUTTONS */

.camera-actions {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 15px;
}

.capture-selfie-btn {
  background: #111827;
  color: white;
}

.capture-selfie-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.cancel-camera-btn {
  border: 1px solid #cbd5e1;
  background: white;
  color: #334155;
  border-radius: 10px;
  padding: 12px 20px;
  cursor: pointer;
}

/* PREVIEW */

.selfie-preview {
  max-width: 420px;
  margin: 0 auto;
  text-align: center;
}

.selfie-preview img {
  width: 100%;
  aspect-ratio: 4 / 5;
  object-fit: cover;
  border-radius: 18px;
  display: block;
  border: 3px solid #22c55e;
}

.selfie-success {
  display: flex;
  align-items: center;
  gap: 12px;

  margin-top: 14px;
  padding: 14px;

  border-radius: 12px;

  background: #f0fdf4;
  border: 1px solid #bbf7d0;

  text-align: left;
}

.selfie-success>span {
  width: 34px;
  height: 34px;

  border-radius: 50%;

  display: flex;
  align-items: center;
  justify-content: center;

  background: #22c55e;
  color: white;
  font-weight: bold;
}

.selfie-success strong {
  color: #166534;
}

.selfie-success p {
  margin: 3px 0 0;
  color: #64748b;
  font-size: 13px;
}

.retake-selfie-btn {
  margin-top: 12px;
  background: white;
  border: 1px solid #cbd5e1;
}

/* ERROR */

.selfie-error {
  margin-top: 12px;
  padding: 12px 15px;

  border-radius: 10px;

  background: #fef2f2;
  border: 1px solid #fecaca;

  color: #dc2626;
  font-size: 14px;
  font-weight: 500;
}

/* MOBILE */

@media (max-width: 600px) {

  .camera-wrapper {
    max-width: 100%;
  }

  .camera-box {
    height: 420px;
    border-radius: 16px;
  }

  .face-frame {
    width: 58%;
    height: 68%;
  }

  .camera-status {
    font-size: 12px;
    padding: 8px 12px;
    bottom: 12px;
  }

  .camera-actions {
    flex-direction: column;
  }

  .capture-selfie-btn,
  .cancel-camera-btn {
    width: 100%;
  }

  .selfie-preview {
    width: 100%;
  }
}

/* ==========================================
   LOAN PROCESSING SECTION
========================================== */

.loan-processing-section {
  width: 100%;
  padding: 40px 20px;
  display: flex;
  justify-content: center;
