  transition: 0.25s ease;
}

.accept-loan-btn:hover:not(:disabled) {
  transform: translateY(-2px);

  box-shadow:
    0 12px 25px rgba(17, 24, 39, 0.20);
}

.accept-loan-btn:disabled {
  opacity: 0.5;

  cursor: not-allowed;
}


/* =========================================================
   REPAYMENT PAGE
   ========================================================= */

.repayment-page {
  padding-bottom: 60px;
}

.repayment-topbar {
  align-items: flex-start;
}

.repayment-eyebrow {
  display: inline-block;

  color: #2563eb;

  font-size: 11px;

  font-weight: 800;

  letter-spacing: 1.6px;

  margin-bottom: 5px;
}

.repayment-topbar h1 {
  margin: 0;

  color: #111827;

  font-size: 30px;
}

.repayment-topbar p {
  margin: 5px 0 0;

  color: #64748b;

  font-size: 14px;
}


/* =========================================================
   REPAYMENT SUMMARY
   ========================================================= */

.repayment-summary-grid {
  width: 100%;

  max-width: 1200px;

  margin: 0 auto 25px;

  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 15px;
}

.repayment-summary-card {
  padding: 22px;

  background: white;

  border-radius: 17px;

  border: 1px solid #e5e7eb;

  box-shadow:
    0 8px 25px rgba(15, 23, 42, 0.06);
}

.repayment-summary-card span {
  display: block;

  color: #64748b;

  font-size: 12px;

  margin-bottom: 8px;
}

.repayment-summary-card strong {
  display: block;

  color: #111827;

  font-size: 21px;
}


/* =========================================================
   REPAYMENT DETAILS
   ========================================================= */

.repayment-details-card {
  width: 100%;

  max-width: 1200px;

  margin: 0 auto;

  background: white;

  border: 1px solid #e5e7eb;

  border-radius: 22px;

  box-shadow:
    0 15px 40px rgba(15, 23, 42, 0.07);

  overflow: hidden;
}

.repayment-details-header {
  padding: 25px 28px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  border-bottom: 1px solid #e5e7eb;
}

.repayment-details-header span {
  color: #2563eb;

  font-size: 11px;

  font-weight: 800;

  letter-spacing: 1.5px;
}

.repayment-details-header h2 {
  margin: 6px 0 0;

  color: #111827;

  font-size: 21px;
}

.loan-status-badge {
  padding: 9px 14px;

  border-radius: 30px;

  background: #dcfce7;

  color: #166534;

  font-size: 11px;

  font-weight: 800;

  letter-spacing: 0.5px;
}


/* =========================================================
   REPAYMENT TABLE
   ========================================================= */

.repayment-table {
  width: 100%;
}

.repayment-row {
  display: grid;

  grid-template-columns:
    1.1fr 1.4fr 1.3fr 1fr 0.9fr;

  align-items: center;

  gap: 15px;

  padding: 17px 28px;

  border-bottom: 1px solid #edf0f4;
}

.repayment-row:last-child {
  border-bottom: none;
}

.repayment-table-head {
  background: #f8fafc;

  color: #64748b;

  font-size: 11px;

  font-weight: 800;

  text-transform: uppercase;

  letter-spacing: 0.7px;
}

.repayment-row span {
  color: #64748b;

  font-size: 14px;
}

.repayment-row strong {
  color: #111827;

  font-size: 14px;
}


/* =========================================================
   PAYMENT STATUS
   ========================================================= */

.repayment-paid {
  color: #16a34a !important;

  font-weight: 700;
}

.repayment-pending {
  color: #d97706 !important;

  font-weight: 700;
}


/* =========================================================
   PAY BUTTON
   ========================================================= */

.repayment-pay-btn {
  border: none;

  padding: 9px 17px;

  border-radius: 9px;

  background:
    linear-gradient(135deg,
      #111827,
      #374151);

  color: white;

  font-size: 13px;

  font-weight: 700;

  cursor: pointer;

  transition: 0.2s ease;
}

.repayment-pay-btn:hover:not(:disabled) {
  transform: translateY(-1px);

  box-shadow:
    0 6px 15px rgba(17, 24, 39, 0.15);
}

.repayment-pay-btn:disabled {
  background: #dcfce7;

  color: #166534;

  cursor: default;
}


/* =========================================================
   QR PAYMENT MODAL
   ========================================================= */

.payment-modal-overlay {
  position: fixed;

  inset: 0;

  z-index: 9999;

  display: flex;

  align-items: center;

  justify-content: center;

  padding: 20px;

  background:
    rgba(15, 23, 42, 0.70);

  backdrop-filter: blur(5px);
}

.payment-modal {
  position: relative;

  width: 100%;

  max-width: 430px;

  padding: 32px;

  background: white;

  border-radius: 22px;

  text-align: center;

  box-shadow:
    0 25px 70px rgba(0, 0, 0, 0.25);

  box-sizing: border-box;

  animation: paymentModalIn 0.25s ease;
}

@keyframes paymentModalIn {
  from {
    opacity: 0;
    transform: translateY(15px) scale(0.97);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.payment-close-btn {
  position: absolute;

  top: 13px;

  right: 15px;

  width: 34px;

  height: 34px;

  border: none;

  border-radius: 50%;

  background: #f1f5f9;

  color: #475569;

  font-size: 23px;

  line-height: 1;

  cursor: pointer;
}

.payment-modal h2 {
  margin: 8px 0 5px;

  color: #111827;

  font-size: 25px;
}

.payment-modal>p {
  color: #64748b;

  font-size: 14px;
}


/* =========================================================
   QR BOX
   ========================================================= */

.qr-box {
  width: 250px;

  height: 250px;

  margin: 20px auto;

  display: flex;

  align-items: center;

  justify-content: center;

  position: relative;

  background: white;

  border: 1px solid #e5e7eb;

  border-radius: 15px;

  padding: 10px;

  box-sizing: border-box;

  overflow: hidden;
}

.qr-box img {
  width: 100%;

  height: 100%;

  object-fit: contain;
}

.qr-fallback {
  position: absolute;

  inset: 0;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  color: #94a3b8;

  font-size: 12px;

  line-height: 1.6;

  background: white;
}

.qr-fallback strong {
  color: #111827;
}

.qr-note {
  margin: 5px 0 20px !important;

  font-size: 13px !important;

  color: #64748b !important;
}


/* =========================================================
   PAYMENT CLOSE
   ========================================================= */

.payment-done-btn {
  width: 100%;

  height: 48px;

  border: none;

  border-radius: 10px;

  background: #111827;

  color: white;

  font-size: 14px;

  font-weight: 700;

  cursor: pointer;

  transition: 0.2s ease;
}

.payment-done-btn:hover {
  background: #2563eb;
}


/* =========================================================
   LOAN PROCESSING / REJECTED
   ========================================================= */

.loan-processing-section {
  width: 100%;

  padding: 50px 20px;

  box-sizing: border-box;
}

.loan-processing-card {
  width: 100%;

  max-width: 800px;

  margin: 0 auto;

  padding: 35px;

  display: flex;

  align-items: center;

  gap: 30px;

  background: white;

  border: 1px solid #e5e7eb;

  border-radius: 22px;

  box-shadow:
    0 15px 40px rgba(15, 23, 42, 0.08);

  box-sizing: border-box;
}

.processing-circle {
  flex-shrink: 0;

  width: 80px;

  height: 80px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 50%;

  background: #eff6ff;
}

.processing-spinner {
  width: 32px;

  height: 32px;

  border: 4px solid #dbeafe;

  border-top-color: #2563eb;

  border-radius: 50%;

  animation: processingSpin 0.8s linear infinite;
}

@keyframes processingSpin {
  to {
    transform: rotate(360deg);
  }
}

.rejected-card {
  border-color: #fecaca;

  background:
    linear-gradient(135deg,
      #ffffff,
      #fff7f7);
}

.rejected-circle {
  background: #fee2e2;
}

.rejected-icon {
  color: #dc2626;

  font-size: 30px;

  font-weight: 700;
}

.processing-content {
  display: flex;

  flex-direction: column;

  align-items: flex-start;
}

.processing-content h2 {
  margin: 5px 0 8px;

  color: #111827;

  font-size: 25px;
}

.processing-content p {
  margin: 0 0 8px;

  color: #64748b;

  font-size: 14px;

  line-height: 1.6;
}

.processing-content strong {
  color: #111827;

  font-size: 14px;
}

.processing-content small {
  margin-top: 5px;

  color: #64748b;

  font-size: 13px;
}

.rejected-label {
  color: #dc2626;
}


/* =========================================================
   HOME USER BAR
   ========================================================= */

.home-user-bar {
  width: 100%;

  padding: 14px 5%;

  display: flex;

  align-items: center;

  justify-content: space-between;

  background: white;

  border-bottom: 1px solid #e5e7eb;

  box-sizing: border-box;
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 900px) {

  .loan-offer-card {
    padding: 30px 22px;
  }

  .offer-calculation {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .repayment-summary-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .repayment-row {
    grid-template-columns:
      1fr 1fr 1fr 1fr auto;

    padding: 15px 20px;
  }
}


@media (max-width: 650px) {

  .loan-offer-page,
  .repayment-page {
    padding: 15px;
  }

  .loan-offer-topbar,
  .repayment-topbar {
    padding: 14px;

    border-radius: 14px;
  }

  .loan-offer-card {
    padding: 25px 16px;

    border-radius: 18px;
  }

  .loan-offer-card h1 {
    font-size: 26px;
  }

  .offer-selection-grid {
    grid-template-columns: 1fr;
  }

  .offer-calculation {
    grid-template-columns: 1fr;
  }

  .repayment-summary-grid {
    grid-template-columns: 1fr 1fr;

    gap: 10px;
  }

  .repayment-summary-card {
    padding: 16px;
  }

  .repayment-summary-card strong {
    font-size: 17px;
  }

  .repayment-details-card {
    border-radius: 16px;
  }

  .repayment-details-header {
    padding: 20px;

    flex-direction: column;

    align-items: flex-start;

    gap: 12px;
  }

  .repayment-table {
    overflow-x: auto;
  }

  .repayment-row {
    min-width: 700px;

    grid-template-columns:
      1fr 1.3fr 1.2fr 1fr 0.8fr;

    padding: 14px 18px;
  }

  .repayment-table-head {
    min-width: 700px;
  }

  .loan-processing-card {
    padding: 25px 20px;

    flex-direction: column;

    text-align: center;
  }

  .processing-content {
    align-items: center;
  }

  .home-user-bar {
    padding: 12px 15px;
  }

  .payment-modal {
    padding: 28px 18px;
  }

  .qr-box {
    width: 220px;

    height: 220px;
  }
}


@media (max-width: 430px) {

  .repayment-summary-grid {
    grid-template-columns: 1fr;
  }

  .profile-avatar {
    width: 40px;

    height: 40px;
  }

  .profile-info strong {
    font-size: 13px;
  }

  .logout-btn {
    padding: 9px 13px;

    font-size: 12px;
  }

  .repayment-topbar h1 {
    font-size: 25px;
  }

  .loan-offer-card h1 {
    font-size: 23px;
  }

  .offer-approved-box strong {
    font-size: 25px;
  }

  .qr-box {
    width: 200px;

    height: 200px;
  }
}